mapper.update:
UPDATE sys_id_sequence
SET max_id = max_id + #{step},
    version = version + 1
WHERE biz_key = #{bizKey}
  AND version = #{version}

mapper.select:
SELECT MAX(max_id)
FROM sys_id_sequence
WHERE biz_key LIKE #{escapedLegacyKeyPattern} ESCAPE '!'
  AND (
    SUBSTRING_INDEX(biz_key, ':', -1) = #{legacyPeriod}
    OR (
      CHAR_LENGTH(#{legacyPeriod}) = 10
      AND CHAR_LENGTH(SUBSTRING_INDEX(biz_key, ':', -1)) IN (10, 12, 14)
      AND LEFT(SUBSTRING_INDEX(biz_key, ':', -1), 10) = #{legacyPeriod}
    )
  )
